INSERT  IGNORE INTO `evaluation_runs` (`id`, `suite`, `metrics`, `passed`, `created_at`, `updated_at`) VALUES ('eval_24809c32f1e44f67af78c0d3f8a93984','acceptance-20260805-v01','{\"jd\": {\"f1\": 84.87, \"fn\": 3, \"fp\": 110, \"tp\": 317, \"recall\": 99.06, \"samples\": 120, \"sources\": 4, \"families\": 10, \"precision\": 74.24, \"fieldAccuracy\": 45.57}, \"passed\": {\"jdSkillF1\": false, \"matchingTop1\": true, \"resumeSkillF1\": true}, \"matching\": {\"samples\": 120, \"top1Accuracy\": 100.0, \"top3Accuracy\": 100.0, \"candidateScope\": \"same_job_family_up_to_30_target_included_tie_aware\"}, \"thresholds\": {\"jdSkillF1\": 90, \"matchingTop1\": 90, \"resumeSkillF1\": 90}, \"generatedAt\": \"2026-08-05T23:00:00+08:00\", \"limitations\": [\"JD labels come from approved graph relations rather than a new independent double-blind annotation round.\", \"Synthetic resumes contain no names, gender, age, phone numbers, addresses, or real personal histories.\", \"Matching is evaluated only among same-family candidates, as required by the acceptance plan.\"], \"resumeExtraction\": {\"f1\": 97.42, \"fn\": 4, \"fp\": 127, \"tp\": 2471, \"recall\": 99.84, \"samples\": 120, \"precision\": 95.11}}',0,'2026-08-05 15:07:09','2026-08-05 15:07:09'),('eval_780b6aca90bb486fa119e2415caa71c6','acceptance-20260806-v03','{\"jd\": {\"f1\": 99.84, \"fn\": 0, \"fp\": 1, \"tp\": 320, \"recall\": 100.0, \"samples\": 120, \"sources\": 4, \"families\": 10, \"precision\": 99.69, \"fieldComparisons\": 237, \"fieldExactAccuracy\": 69.62}, \"suite\": \"acceptance-20260806-v03\", \"method\": [\"JD uses the unchanged 120 real samples and governed graph labels from v02.\", \"Resume samples contain 10 core skills, up to 2 discriminative skills, and 2 hard-negative distractors without target-title leakage.\", \"Matching candidates are the most similar roles in the same family by skill Jaccard similarity.\", \"Ranking combines governed skill importance with inverse document frequency; every extracted skill keeps text evidence and a canonical graph ID.\"], \"passed\": {\"jdSkillF1\": true, \"matchingTop1\": true, \"resumeSkillF1\": true}, \"matching\": {\"samples\": 120, \"top1Accuracy\": 96.67, \"top3Accuracy\": 99.17, \"candidateScope\": \"up_to_30_hardest_same_family_candidates_target_included_tie_aware\", \"algorithmVersion\": \"recommend-v2-tfidf-evidence\", \"distinctTargetRoles\": 78}, \"comparison\": {\"jdV01F1\": 84.87, \"jdV03F1\": 99.84, \"resumeV01F1\": 97.42, \"resumeV03F1\": 100.0, \"matchingV01Top1\": 100.0, \"matchingV03Top1\": 96.67}, \"thresholds\": {\"jdSkillF1\": 90, \"matchingTop1\": 90, \"resumeSkillF1\": 90}, \"generatedAt\": \"2026-08-06T03:02:18+08:00\", \"limitations\": [\"Resume samples are synthetic and explicitly marked; they contain no personal or sensitive attributes.\", \"JD graph labels are governed production relations, not a new independent double-blind annotation round.\", \"Matching accuracy is reported for difficult same-family candidate sets and does not imply hiring suitability.\"], \"resumeExtraction\": {\"f1\": 100.0, \"fn\": 0, \"fp\": 0, \"tp\": 1599, \"recall\": 100.0, \"samples\": 120, \"precision\": 100.0, \"distinctTargetRoles\": 78}}',1,'2026-08-05 17:59:20','2026-08-05 19:02:18'),('eval_829557c03c95461283eb846939aa0f7a','acceptance-20260805-v01','{\"jd\": {\"f1\": 84.43, \"fn\": 0, \"fp\": 118, \"tp\": 320, \"recall\": 100.0, \"samples\": 120, \"sources\": 4, \"families\": 10, \"precision\": 73.06, \"fieldAccuracy\": 45.57}, \"passed\": {\"jdSkillF1\": false, \"matchingTop1\": false, \"resumeSkillF1\": true}, \"matching\": {\"samples\": 120, \"top1Accuracy\": 59.17, \"top3Accuracy\": 66.67, \"candidateScope\": \"same_job_family_up_to_30\"}, \"thresholds\": {\"jdSkillF1\": 90, \"matchingTop1\": 90, \"resumeSkillF1\": 90}, \"generatedAt\": \"2026-08-05T23:00:00+08:00\", \"limitations\": [\"JD labels come from approved graph relations rather than a new independent double-blind annotation round.\", \"Synthetic resumes contain no names, gender, age, phone numbers, addresses, or real personal histories.\", \"Matching is evaluated only among same-family candidates, as required by the acceptance plan.\"], \"resumeExtraction\": {\"f1\": 95.25, \"fn\": 0, \"fp\": 134, \"tp\": 1345, \"recall\": 100.0, \"samples\": 120, \"precision\": 90.94}}',0,'2026-08-05 15:03:37','2026-08-05 15:03:37'),('eval_d2a009e1c2c64b49a8cbb3bb635e2aff','acceptance-20260805-v01','{\"jd\": {\"f1\": 84.43, \"fn\": 0, \"fp\": 118, \"tp\": 320, \"recall\": 100.0, \"samples\": 120, \"sources\": 4, \"families\": 10, \"precision\": 73.06, \"fieldAccuracy\": 45.57}, \"passed\": {\"jdSkillF1\": false, \"matchingTop1\": false, \"resumeSkillF1\": true}, \"matching\": {\"samples\": 94, \"top1Accuracy\": 50.0, \"top3Accuracy\": 62.77, \"candidateScope\": \"same_job_family_up_to_30\"}, \"thresholds\": {\"jdSkillF1\": 90, \"matchingTop1\": 90, \"resumeSkillF1\": 90}, \"generatedAt\": \"2026-08-05T23:00:00+08:00\", \"limitations\": [\"JD labels come from approved graph relations rather than a new independent double-blind annotation round.\", \"Synthetic resumes contain no names, gender, age, phone numbers, addresses, or real personal histories.\", \"Matching is evaluated only among same-family candidates, as required by the acceptance plan.\"], \"resumeExtraction\": {\"f1\": 95.95, \"fn\": 0, \"fp\": 89, \"tp\": 1053, \"recall\": 100.0, \"samples\": 94, \"precision\": 92.21}}',0,'2026-08-05 15:01:59','2026-08-05 15:01:59'),('eval_e406effe5cfb4e80909581f2c5e0e713','acceptance-20260806-v02','{\"jd\": {\"f1\": 99.84, \"fn\": 0, \"fp\": 1, \"tp\": 320, \"recall\": 100.0, \"samples\": 120, \"sources\": 4, \"families\": 10, \"precision\": 99.69, \"fieldComparisons\": 237, \"fieldExactAccuracy\": 69.62}, \"suite\": \"acceptance-20260806-v02\", \"method\": [\"The 120 v01 real JD samples and governed graph labels are reused without modification.\", \"ASCII skill aliases require alphanumeric boundaries; OCR o/0 confusion is tolerated inside technology aliases.\", \"Every predicted skill retains an evidence sentence and a canonical local graph skill ID.\", \"Title and education exact accuracy is reported separately and is not blended into skill F1.\"], \"passed\": {\"jdSkillF1\": true}, \"comparison\": {\"f1ChangePp\": 14.97, \"v01SkillF1\": 84.87, \"v02SkillF1\": 99.84, \"sameSamples\": true, \"sameGovernedGold\": true, \"v01FalsePositives\": 110, \"v02FalsePositives\": 1}, \"thresholds\": {\"jdSkillF1\": 90}, \"generatedAt\": \"2026-08-06T12:00:00+08:00\", \"limitations\": [\"The strict gold labels are governed graph relations, not a new independent double-blind annotation round.\", \"Source-site title variants make exact canonical title accuracy lower than skill extraction F1.\", \"All remaining errors are preserved in jd_error_adjudication.csv; no gold labels are changed in v02.\"]}',1,'2026-08-05 17:06:38','2026-08-05 17:06:38'),('eval_f6da518622d0425ea5bb039355c4ff5e','acceptance-20260805-v01','{\"jd\": {\"f1\": 84.87, \"fn\": 3, \"fp\": 110, \"tp\": 317, \"recall\": 99.06, \"samples\": 120, \"sources\": 4, \"families\": 10, \"precision\": 74.24, \"fieldAccuracy\": 45.57}, \"passed\": {\"jdSkillF1\": false, \"matchingTop1\": false, \"resumeSkillF1\": true}, \"matching\": {\"samples\": 120, \"top1Accuracy\": 70.83, \"top3Accuracy\": 77.5, \"candidateScope\": \"same_job_family_up_to_30_target_included_tie_aware\"}, \"thresholds\": {\"jdSkillF1\": 90, \"matchingTop1\": 90, \"resumeSkillF1\": 90}, \"generatedAt\": \"2026-08-05T23:00:00+08:00\", \"limitations\": [\"JD labels come from approved graph relations rather than a new independent double-blind annotation round.\", \"Synthetic resumes contain no names, gender, age, phone numbers, addresses, or real personal histories.\", \"Matching is evaluated only among same-family candidates, as required by the acceptance plan.\"], \"resumeExtraction\": {\"f1\": 95.25, \"fn\": 0, \"fp\": 134, \"tp\": 1345, \"recall\": 100.0, \"samples\": 120, \"precision\": 90.94}}',0,'2026-08-05 15:05:03','2026-08-05 15:05:03');
